def transform(grid):
 h,w=len(grid),len(grid[0]); seen=set(); comps=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c] and (r,c) not in seen:
    stack=[(r,c)]; seen.add((r,c)); obj=set()
    while stack:
     y,x=stack.pop(); obj.add((y,x))
     for dy in (-1,0,1):
      for dx in (-1,0,1):
       q=(y+dy,x+dx)
       if 0<=q[0]<h and 0<=q[1]<w and q not in seen and grid[q[0]][q[1]]==grid[r][c]:
        seen.add(q); stack.append(q)
    comps.append(obj)
 if not comps:return [row[:] for row in grid]
 template=max(comps,key=len); top=min(r for r,c in template); left=min(c for r,c in template)
 pat={(r-top,c-left) for r,c in template}; ph=max(r for r,c in pat)+1; pw=max(c for r,c in pat)+1
 out=[[0]*w for _ in range(h)]
 for comp in comps:
  color=grid[next(iter(comp))[0]][next(iter(comp))[1]]
  candidates=[]
  for y in range(-ph+1,h):
   for x in range(-pw+1,w):
    visible={(y+a,x+b) for a,b in pat if 0<=y+a<h and 0<=x+b<w}
    if visible==comp:candidates.append((y,x))
  if candidates:
   y,x=max(candidates,key=lambda p:p[0])
   for a,b in pat:
    yy=y+a+ph; xx=x+b
    if 0<=yy<h and 0<=xx<w:out[yy][xx]=color
 return out

